"""Carrega e valida a configuração editável pelo financeiro (pasta config/).

- cadastro_lojistas.csv: CNPJ, nome, EC da Orbe e status. Única fonte do EC.
- regras_negocio.csv: cada regra tem um `tipo` de uma lista fechada. O motor só
  executa tipos conhecidos, a partir da coluna `parametros`, no formato
  chave=valor separado por "|" (ex.: banco=AURORA|contem=PIX ENVIADO|conta=2.1.01.001).
  Listas dentro de um valor usam vírgula (ex.: aceitos=APROVADO,APROVADO C/ RESSALVA).
  Números aceitam vírgula ou ponto decimal.
- MANUAL nunca é executado: só gera pendência com o_que_fazer e quem_decide.
- Colunas de texto livre (situacao, como_identificar, o_que_fazer...) não são
  interpretadas pelo código; servem para pessoas e para explicar pendências.

Erro de configuração para o fechamento com mensagem em português indicando o id
da regra e como corrigir.
"""
from __future__ import annotations

import csv
import io
import re
from dataclasses import dataclass, field
from datetime import date
from decimal import Decimal, InvalidOperation
from pathlib import Path

import pandas as pd

from .leitores.comum import ErroLeitura, ler_texto, normalizar

SEPARADOR_PARAMETROS = "|"
TIPOS = ("TAXA_EXCECAO", "PARAMETRO", "IGNORAR_DUPLICADO", "EXCLUIR_E_PENDENCIA",
         "CLASSIFICAR_CONTA", "MANUAL")

# Vocabulário que o motor sabe executar (formato, não regra de negócio).
PRODUTOS = {
