                    "motivo": _motivo_sem_taxa(situacao, produto, parcelas, data_taxa, ref)}
        regra_id = f"planilha:{ref}"

    comissao = arredondar(pct(taxa, r.valor_bruto), config.parametro("arredondamento", data_mov))
